@font-face{font-family:Tajawal;font-weight:400;src:url(fonts/tajawal-400.woff2) format("woff2");font-display:swap}
@font-face{font-family:Tajawal;font-weight:500;src:url(fonts/tajawal-500.woff2) format("woff2");font-display:swap}
@font-face{font-family:Tajawal;font-weight:700;src:url(fonts/tajawal-700.woff2) format("woff2");font-display:swap}
:root{--felt:#1d4a43;--felt-d:#12302b;--paper:#eef1ee;--card:#fff;--ink:#17211f;--muted:#5f6c69;--line:#d6ddd9;--stamp:#b0332a;--brass:#a9822c;--accent:#1d4a43;--on:#fff;--soft:#e4ece8;--rad:10px}
html[data-theme=dark]{--felt:#5fb3a3;--felt-d:#0c1a17;--paper:#101816;--card:#17221f;--ink:#e9efed;--muted:#9fb0ab;--line:#2c3b37;--stamp:#ff8a7e;--brass:#d7b45c;--accent:#5fb3a3;--on:#08201b;--soft:#1e2d29}
*{box-sizing:border-box}
html,body{margin:0;background:var(--paper);color:var(--ink)}
body{font:400 15px/1.65 Tajawal,system-ui,sans-serif;-webkit-text-size-adjust:100%;font-variant-numeric:tabular-nums}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer;background:none;border:0;padding:0;text-align:inherit}
a{color:var(--accent)}
small{font-size:12.5px;color:var(--muted)}
:focus-visible{outline:3px solid var(--brass);outline-offset:2px;border-radius:6px}
.ic{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}
.flip{transform:scaleX(-1)}
.grow{flex:1}.muted{color:var(--muted)}
/* الهيكل */
#shell{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:100vh}
#rail{background:var(--felt-d);color:#e7f0ed;display:flex;flex-direction:column;padding:22px 14px;position:sticky;top:0;height:100vh;gap:20px}
html[data-theme=dark] #rail{border-inline-end:1px solid var(--line)}
.brand{display:grid;gap:2px;padding:6px 8px 14px;border-bottom:1px solid #ffffff22}
.brand .ic{width:30px;height:30px;color:#d7b45c;margin-bottom:8px}
.brand strong{font-size:18px;line-height:1.3}.brand small{color:#a9c2bb}
.rail-nav{display:grid;gap:4px}
#rail button{display:flex;gap:12px;align-items:center;padding:10px 12px;border-radius:8px;color:#cfe0db}
#rail button:hover{background:#ffffff12}
#rail button.cur{background:#ffffff1f;color:#fff;font-weight:700;box-shadow:inset -3px 0 #d7b45c}
#rail .gear{margin-top:auto}
#col{min-width:0;padding-bottom:40px}
#top{display:flex;align-items:center;gap:10px;max-width:900px;margin:0 auto;padding:24px 28px 0}#top h1{font-size:22px}
body[data-detail=case] #top,body[data-detail=client] #top{display:none}
#view{max-width:900px;margin:0 auto;padding:26px 28px 40px;outline:0}
#tabs{display:none}
/* عناصر */
.btn{display:inline-flex;align-items:center;gap:7px;padding:9px 16px;border-radius:8px;font-weight:500;border:1px solid var(--line);background:var(--card);min-height:40px;justify-content:center}
.btn.pri{background:var(--felt);color:var(--on);border-color:var(--felt)}
html:not([data-theme=dark]) .btn.pri{color:#fff}
.btn.quiet{background:transparent}
.btn.danger{color:var(--stamp);border-color:var(--stamp);background:transparent}
.btn.small{padding:5px 12px;min-height:34px;font-size:14px}
.btn:hover{filter:brightness(1.06)}
.icon{display:grid;place-items:center;width:40px;height:40px;border-radius:8px}
.icon:hover{background:var(--soft)}
h1,h2,h3{margin:0;line-height:1.3}
.hello{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:20px}
.hello h1{font-size:34px;font-weight:700;letter-spacing:-.01em}
.hello p{margin:0;color:var(--muted)}
.figs{display:flex;gap:4px 18px;flex-wrap:wrap;color:var(--muted);font-size:14px}.figs b{color:var(--ink);font-size:18px;margin-inline-end:4px}
.blk{margin-top:26px}.blk h2,.sec-h h3{font-size:16px;font-weight:700}
.sec-h{display:flex;justify-content:space-between;align-items:center;margin:26px 0 10px;gap:10px}
.sec-h small{margin-inline-start:6px}
/* قسيمة الجلسة (العنصر المميز) */
.slip{display:flex;width:100%;justify-content:space-between;align-items:center;gap:18px;background:var(--felt);color:#f3faf8;padding:22px 26px;border-radius:14px;position:relative;
  --n:11px;-webkit-mask:radial-gradient(circle var(--n) at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle var(--n) at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat;mask:radial-gradient(circle var(--n) at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle var(--n) at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat}
html[data-theme=dark] .slip{background:#16423b}
.slip-l{display:grid;gap:3px;min-width:0}
.slip small{color:#bfe0d8}.slip strong{font-size:22px;line-height:1.35}.slip em{font-style:normal;color:#f1dc9b}
.slip-l span{color:#d9ece7}
.stamp{flex:none;width:92px;height:92px;border-radius:50%;border:3px double #ffb3a9;color:#ffb3a9;display:grid;place-content:center;text-align:center;transform:rotate(-9deg);background:#0000;line-height:1.1}
.stamp b{font-size:34px}.stamp small{color:inherit;font-size:13px}
.stamp.now{background:#b0332a;border-color:#ffd0ca;color:#fff}.stamp.now b{font-size:24px}
/* قوائم */
.list{display:grid;background:var(--card);border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}
.row{display:flex;align-items:center;gap:12px;width:100%;padding:12px 14px;border-bottom:1px solid var(--line);text-align:start;min-height:56px}
.row:last-child{border-bottom:0}
button.row:hover,.tl-i:hover{background:var(--soft)}
.row.done .main{opacity:.55;text-decoration:line-through}
.main{flex:1;min-width:0;display:grid}.main strong{font-weight:500;overflow:hidden;text-overflow:ellipsis}
.main small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.as-btn{text-align:start}
.when{width:64px;white-space:nowrap;display:grid;text-align:center;flex:none}.when b{font-size:15px}
.tag{font-size:12.5px;padding:2px 10px;border-radius:99px;background:var(--soft);color:var(--ink);white-space:nowrap}
.tag.warn{background:var(--stamp);color:#fff}
.amt,.owe{color:var(--stamp);font-weight:700;white-space:nowrap}
.owe{font-size:13px;color:var(--stamp)}
.side{display:grid;justify-items:end;gap:2px}
.dot{width:10px;height:10px;border-radius:50%;background:var(--c);flex:none}
.av{width:38px;height:38px;border-radius:50%;background:var(--felt);color:var(--on);display:grid;place-items:center;font-weight:700;flex:none}
html:not([data-theme=dark]) .av{color:#fff}
.chk{width:26px;height:26px;border-radius:50%;border:2px solid var(--line);display:grid;place-items:center;flex:none;color:#0000}
.chk.on{background:var(--felt);border-color:var(--felt);color:#fff}
.chk .ic{width:15px;height:15px;stroke-width:3}
.calm{color:var(--muted);margin:10px 2px}.calm.sm{font-size:14px}
.empty{text-align:center;padding:44px 16px;display:grid;justify-items:center;gap:6px}
.empty-mark{width:64px;height:64px;border-radius:50%;background:var(--soft);display:grid;place-items:center;color:var(--felt);margin-bottom:6px}
.empty-mark .ic{width:30px;height:30px}.empty h3{font-size:18px}.empty p{margin:0 0 12px;color:var(--muted);max-width:34ch}
/* بحث وفلاتر */
.bar{margin-bottom:12px}
.search{display:flex;align-items:center;gap:10px;background:var(--card);border:1px solid var(--line);border-radius:var(--rad);padding:0 14px}
.search input{flex:1;border:0;background:none;padding:12px 0;outline:0;min-width:0}
.search:focus-within{outline:3px solid var(--brass)}
.chips{display:flex;gap:8px;overflow-x:auto;padding-bottom:10px;margin-bottom:6px;scrollbar-width:none}
.chip{padding:6px 14px;border-radius:99px;border:1px solid var(--line);background:var(--card);white-space:nowrap;font-size:14px}
.chip.on{background:var(--felt);color:var(--on);border-color:var(--felt)}
html:not([data-theme=dark]) .chip.on{color:#fff}
/* تفاصيل القضية */
.case-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.back{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--line);background:var(--card);transform:scaleX(-1)}
.case-t{flex:1;min-width:200px}.case-t h1{font-size:24px}.st{display:flex;gap:7px;align-items:center;color:var(--muted);font-size:13px}
.case-a{display:flex;gap:6px}
.facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:0;margin:18px 0 6px;background:var(--card);border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}
.facts>div{padding:11px 14px;border-bottom:1px solid var(--line);border-inline-end:1px solid var(--line)}
.facts dt{font-size:12.5px;color:var(--muted)}.facts dd{margin:0;font-weight:500}.facts dd small{display:block;font-weight:400}
.facts.one{grid-template-columns:1fr}
.subtabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin-top:20px;overflow-x:auto;scrollbar-width:none}
.subtabs button{padding:10px 14px;color:var(--muted);border-bottom:3px solid #0000;white-space:nowrap;display:flex;gap:6px;align-items:center}
.subtabs button.on{color:var(--ink);font-weight:700;border-color:var(--brass)}
.subtabs i{font-style:normal;font-size:11.5px;background:var(--stamp);color:#fff;border-radius:99px;min-width:19px;height:19px;display:grid;place-items:center;padding:0 5px}
.tl{display:grid;border-inline-start:2px solid var(--line);margin-inline-start:6px}
.tl-i{display:flex;gap:14px;padding:12px 14px;width:100%;text-align:start;border-radius:8px;position:relative}
.tl-i::before{content:"";position:absolute;inset-inline-start:-7.5px;top:20px;width:12px;height:12px;border-radius:50%;background:var(--card);border:2px solid var(--muted)}
.tl-i.next::before{background:var(--stamp);border-color:var(--stamp)}
.tl-d{display:grid;width:52px;flex:none;line-height:1.3}.tl-d b{font-size:15px}
.tl-b{display:grid;gap:2px;min-width:0}.tl-b em{font-style:normal;color:var(--muted);font-weight:400;margin-inline-start:6px}
.res{background:var(--soft);padding:8px 12px;border-radius:8px;white-space:pre-wrap;margin-top:4px}.res.plain{background:none;padding:0;margin:0}
.subject{margin-top:22px}.subject h3{font-size:14px;color:var(--muted);margin-bottom:4px}.subject p{margin:0;white-space:pre-wrap}
.foot{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}.foot.left{justify-content:flex-start}
.ledger{display:grid;grid-template-columns:repeat(3,1fr);background:var(--card);border:1px solid var(--line);border-radius:var(--rad);margin:14px 0 8px}
.ledger>div{padding:12px 16px;display:grid}.ledger>div+div{border-inline-start:1px solid var(--line)}
.ledger b{font-size:22px}.ledger.big b{font-size:28px}.ledger .owed b{color:var(--stamp)}
.meter{height:7px;background:var(--soft);border-radius:9px;overflow:hidden;margin:8px 0}.meter i{display:block;height:100%;background:var(--felt)}.meter i.hot{background:var(--stamp)}
/* التقويم */
.cal-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.cal-h h2{font-size:20px}
.grid{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
.gh{text-align:center;font-size:12.5px;color:var(--muted);padding:4px 0}
.cell{aspect-ratio:1/.9;border-radius:9px;background:var(--card);border:1px solid var(--line);display:grid;place-items:center;align-content:center;gap:2px;position:relative;min-height:44px}
.cell.off{background:none;border:0}
.cell.tod b{color:var(--stamp)}.cell.tod{border-color:var(--stamp)}
.cell.sel{background:var(--felt);color:var(--on);border-color:var(--felt)}html:not([data-theme=dark]) .cell.sel{color:#fff}.cell.sel b{color:inherit}
.pips{display:flex;gap:3px;font-style:normal}.pips u{width:5px;height:5px;border-radius:50%;background:var(--brass);display:block}.cell.sel .pips u{background:#fff}
/* نماذج ونوافذ */
#sheet-root .veil,.ask .veil{position:fixed;inset:0;background:#0a1210aa;z-index:30}
.sheet{position:fixed;z-index:31;inset-block:0;inset-inline-start:0;width:min(480px,100%);background:var(--paper);display:flex;flex-direction:column;box-shadow:0 0 40px #0006}
.sheet.wide{width:min(720px,100%)}
.sheet header{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid var(--line);background:var(--card)}
.sheet h2{font-size:18px}.sheet-body{padding:18px;overflow:auto;flex:1}
.frm{display:flex;flex-wrap:wrap;gap:12px}
.fld{display:grid;gap:5px;flex:1 1 100%}.fld.half{flex:1 1 calc(50% - 6px)}
.fld>span{font-size:13.5px;color:var(--muted)}
.fld input,.fld select,.fld textarea{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px 12px;min-height:44px;width:100%;resize:vertical}
.fld input.bad,.fld select.bad,.fld textarea.bad{border-color:var(--stamp)}
.actions{flex:1 1 100%;display:flex;gap:8px;align-items:center;margin-top:8px}
.note{font-size:13.5px;color:var(--muted);background:var(--soft);padding:10px 12px;border-radius:8px;margin:8px 0}
.doc-text{width:100%;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:14px;line-height:1.9;margin-bottom:12px;min-height:200px;height:calc(100vh - 340px)}
.tpl{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
.tpl-i{display:flex;gap:10px;align-items:center;padding:14px;background:var(--card);border:1px solid var(--line);border-radius:var(--rad)}.tpl-i:hover{border-color:var(--felt)}
.ask{position:fixed;inset:0;z-index:40;display:grid;place-items:center;padding:16px}.ask .box{position:relative;background:var(--card);border-radius:12px;padding:20px;width:min(380px,100%);z-index:41}
.ask p{margin:0 0 14px;font-weight:500}
#toast{position:fixed;bottom:24px;inset-inline:0;margin:auto;width:fit-content;max-width:92vw;background:var(--ink);color:var(--paper);padding:10px 18px;border-radius:99px;opacity:0;pointer-events:none;transform:translateY(8px);transition:opacity .2s,transform .2s;z-index:50;text-align:center}
#toast.on{opacity:1;transform:none}
.calc{background:var(--card);border:1px solid var(--line);border-radius:var(--rad);padding:14px}.calc form{display:flex;flex-wrap:wrap;gap:10px}
#calc-out{display:grid;gap:8px;margin-top:12px}.res-l{display:grid;background:var(--soft);padding:10px 14px;border-radius:8px}.res-l strong{font-size:19px}
.store{background:var(--card);border:1px solid var(--line);border-radius:var(--rad);padding:14px}.store p{margin:6px 0}
/* طباعة */
#print-area{display:none}
.paper{font-family:Tajawal,serif;color:#000;background:#fff;padding:0}
.lh{display:flex;justify-content:space-between;border-bottom:3px double #000;padding-bottom:10px;margin-bottom:22px}
.lh div{display:grid}.lh strong{font-size:20px}.lh-r{text-align:end}
.paper-body{font-size:16px;line-height:2.1}.ph{text-align:center;font-size:20px;margin:6px 0 16px}
.pt{width:100%;border-collapse:collapse}.pt th,.pt td{border:1px solid #000;padding:6px 8px;text-align:start}
@media print{body.printing #shell,body.printing #sheet-root,body.printing #toast{display:none!important}body.printing #print-area{display:block}body{background:#fff}}
/* هاتف */
@media(max-width:820px){
  #shell{display:block}#rail{display:none}
  #top{max-width:none;margin:0;gap:8px;position:sticky;top:0;z-index:5;background:var(--paper);padding:10px 16px!important;border-bottom:1px solid var(--line)}
  #top h1{font-size:20px}
  body[data-detail=case] #top,body[data-detail=client] #top{display:none}
  #top .gear-m{display:grid}
  #view{padding:16px 16px 96px}
  #tabs{display:grid;grid-template-columns:repeat(5,1fr);position:fixed;bottom:0;inset-inline:0;background:var(--card);border-top:1px solid var(--line);z-index:10;padding-bottom:env(safe-area-inset-bottom)}
  #tabs button{display:grid;justify-items:center;gap:1px;padding:8px 0 7px;font-size:11.5px;color:var(--muted);min-height:56px}
  #tabs button.cur{color:var(--felt);font-weight:700}#tabs button.cur .ic{stroke-width:2.3}
  .hello h1{font-size:28px}
  .slip{padding:18px 18px}.slip strong{font-size:19px}.stamp{width:76px;height:76px}.stamp b{font-size:28px}
  .sheet,.sheet.wide{inset:auto 0 0 0;width:100%;max-height:92vh;border-radius:16px 16px 0 0}
  .fld.half{flex-basis:calc(50% - 6px)}
  .ledger b,.ledger.big b{font-size:20px}.ledger>div{padding:10px}
  .case-t h1{font-size:21px}
  .facts{grid-template-columns:1fr 1fr}.subtabs button{padding:10px 9px}.subtabs{gap:0}
  #toast{bottom:84px}
}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
/* v1.1 */
.chip i{font-style:normal;font-size:11.5px;opacity:.75;margin-inline-start:6px;background:#0001;border-radius:99px;padding:0 6px}
.chip.on i{background:#fff3;opacity:1}
.btns{display:flex;gap:6px}
.files{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px}
.file{display:grid;gap:3px;text-align:start;background:var(--card);border:1px solid var(--line);border-radius:var(--rad);padding:8px;align-content:start}
.file:hover{border-color:var(--felt)}
.thumb{aspect-ratio:4/3;border-radius:7px;background:var(--soft);display:grid;place-items:center;overflow:hidden;margin-bottom:4px}
.thumb img{width:100%;height:100%;object-fit:cover}.thumb b{font-size:17px;color:var(--felt);letter-spacing:.02em}
.fn{font-size:13.5px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.viewer{display:grid;place-items:center;background:var(--soft);border-radius:var(--rad);padding:12px;margin-bottom:12px;max-height:56vh;overflow:auto}
.viewer img{max-width:100%;max-height:50vh;border-radius:6px}.bigk{font-size:34px;font-weight:700;color:var(--felt);padding:36px}
.reader{background:var(--card);border:1px solid var(--line);border-radius:var(--rad);padding:16px;line-height:2;max-height:52vh;overflow:auto;margin-bottom:12px}
.lib-h{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.lib-h h2{font-size:22px}
.posts{display:grid;gap:10px;margin-bottom:18px}
.post{background:var(--felt);color:#f3faf8;border-radius:12px;padding:14px 18px}.post small{color:#bfe0d8}.post h3{font-size:17px;margin:2px 0}.post p{margin:0;white-space:pre-wrap}
html[data-theme=dark] .post{background:#16423b}
.av.sq{border-radius:9px;background:var(--soft);color:var(--ink);font-size:18px}
.choice{display:grid;gap:10px}.tpl-i.big{padding:18px;text-align:start}.tpl-i.big span{display:grid}.tpl-i.big small{font-weight:400}.tpl-i:disabled{opacity:.45;cursor:not-allowed}
.toks{display:flex;flex-wrap:wrap;gap:6px;flex:1 1 100%}.toks .chip{padding:3px 10px;font-size:13px}
.live{flex:1 1 100%;margin:2px 0 0;padding:9px 12px;background:var(--soft);border-radius:8px;font-weight:500}
.doc-text.sm{height:auto;min-height:220px}
.tpl.lead{margin-top:12px}.tpl-i.add{border-style:dashed}
@media(max-width:820px){#tabs{grid-template-columns:repeat(6,1fr)}#tabs button{font-size:10.5px}.files{grid-template-columns:repeat(2,1fr)}}

/* أنواع القضايا الهرمية */
.tpick{width:100%;text-align:start;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:inherit;font:inherit}
.tpanel{margin-top:6px;border:1px solid var(--line);border-radius:12px;padding:8px;background:var(--card)}
.kl{max-height:42vh;overflow:auto}.kr{display:flex;align-items:center;gap:2px;padding:2px 0;padding-inline-start:calc(var(--lv,0)*14px);flex-wrap:wrap}
.kn{flex:1 1 80px;min-width:0;text-align:start;background:none;border:0;color:inherit;font:inherit;padding:8px 4px;overflow-wrap:anywhere}.kn.on{font-weight:700;color:var(--felt)}
.kt,.kt0{flex:none;width:30px;height:34px}.kt{background:none;border:0;color:inherit;transition:transform .15s}.kt.o{transform:rotate(-90deg)}
.ka{display:flex;gap:2px;margin-inline-start:auto}.ka button{min-width:32px;min-height:34px;border:1px solid var(--line);background:none;border-radius:8px;color:inherit;font:inherit;font-size:13px}.ka .arm{background:#b3261e;color:#fff;border-color:#b3261e;padding:0 8px}
.kadd{display:flex;gap:8px;margin-top:8px}.kadd input,.krn{flex:1;min-width:0;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:inherit;font:inherit}
